import unittest
import warnings
import inspect
import importlib.util
import sys

from genie.abstract.decorator import deprecated

_MODULE_ALIAS = 'genie.tests.abstract.test_decorator'
if __name__ != _MODULE_ALIAS:
    # AbstractTree imports the pointer path below; keep top-level test runs
    # from loading a second copy of this module.
    sys.modules[_MODULE_ALIAS] = sys.modules[__name__]


def _module_available(name):
    try:
        return importlib.util.find_spec(name) is not None
    except (ImportError, AttributeError, ValueError):
        return False


class _Device(object):
    def __init__(self, os='iosxe', revision=None):
        self.name = 'device'
        self.os = os
        self.custom = {}
        self.abstraction = {}
        if revision is not None:
            self.revision = revision


def _revision_tree(top, old_target, latest_target, feature=None):
    from genie.abstract.package import AbstractTree

    data = {
        top: {
            'folders': {
                'iosxe': {
                    'package': 'genie.tests.abstract',
                    'module_name': 'test_decorator',
                    'class': old_target,
                    'tokens': {'os': 'iosxe'},
                    'folders': {
                        'rev1': {
                            'package': 'genie.tests.abstract',
                            'module_name': 'test_decorator',
                            'class': latest_target,
                            'tokens': {'revision': '1'},
                        },
                    },
                },
            },
        },
    }

    return AbstractTree.from_json(data, feature=feature)


@deprecated
def _deprecated_revision_api(device):
    return 'old', device


def _latest_revision_api(device):
    return 'latest', device


@deprecated
class _DeprecatedRevisionClass(object):
    def __init__(self, device):
        self.device = device


class _LatestRevisionClass(object):
    def __init__(self, device):
        self.device = device


class _DeprecatedMemberClass(object):
    @deprecated
    def cli(self, output=''):
        return {'key': 'Hello World'}


class _LatestMemberClass(object):
    def cli(self, output=''):
        return {'key': 'Hello World from revision'}


