    def test_deprecated(self):
        from genie.abstract.decorator import deprecated

        @deprecated
        def old_function(device, value, **kwargs):
            return device, value, kwargs

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_function('device', 'value', key='argument')

        expected_message = '{}.{} is deprecated.'.format(
            old_function.__module__, old_function.__qualname__)
        self.assertEqual(result, ('device', 'value', {'key': 'argument'}))
        self.assertEqual(inspect.getfullargspec(old_function).args,
                         ['device', 'value'])
        self.assertEqual(len(caught), 1)
        self.assertIs(caught[0].category, FutureWarning)
        self.assertEqual(str(caught[0].message), expected_message)
        self.assertEqual(old_function.__deprecated__, expected_message)

    def test_deprecated_with_message(self):
        from genie.abstract.decorator import deprecated

        message = 'Use new_function instead.'

        @deprecated(message)
        def old_function(device):
            return device

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_function('device')

        self.assertEqual(result, 'device')
        self.assertEqual(inspect.getfullargspec(old_function).args,
                         ['device'])
        self.assertEqual(len(caught), 1)
        self.assertIs(caught[0].category, FutureWarning)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. {}'.format(
                old_function.__module__,
                old_function.__qualname__,
                message))
        self.assertEqual(old_function.__deprecated__, message)

    def test_deprecated_with_message_identifies_original_api(self):
        from genie.abstract.decorator import deprecated

        @deprecated('please use create_empty_file()')
        def touch_file(device, directory, file_name, overwrite=False):
            return device, directory, file_name, overwrite

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = touch_file(
                'device', 'bootflash:/', 'packages.conf', overwrite=True)

        self.assertEqual(
            result,
            ('device', 'bootflash:/', 'packages.conf', True))
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. please use create_empty_file()'.format(
                touch_file.__module__,
                touch_file.__qualname__))

    def test_deprecated_category_override(self):
        from genie.abstract.decorator import deprecated

        @deprecated('Use new_function instead.', category=DeprecationWarning)
        def old_function():
            return 'ok'

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_function()

        self.assertEqual(result, 'ok')
        self.assertEqual(len(caught), 1)
        self.assertIs(caught[0].category, DeprecationWarning)

    def test_deprecated_can_be_suppressed(self):
        from genie.abstract.decorator import deprecated

        @deprecated
        def old_function():
            return 'ok'

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('ignore', FutureWarning)
            result = old_function()

        self.assertEqual(result, 'ok')
        self.assertEqual(len(caught), 0)

    def test_deprecated_category_none_does_not_warn(self):
        from genie.abstract.decorator import deprecated

        @deprecated('Use new_function instead.', category=None)
        def old_function():
            return 'ok'

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_function()

        self.assertEqual(result, 'ok')
        self.assertEqual(len(caught), 0)

    def test_deprecated_abstract_context_latest_revision(self):
        from genie.abstract.decorator import with_deprecation_context

        top = 'deprecated_revision_api'
        abstract_tree = _revision_tree(
            top, '_deprecated_revision_api', '_latest_revision_api')
        tokens = {'os': ['iosxe'], 'revision': [None]}
        matrix_ptr = next(abstract_tree.iter_lookup(
            tokens=tokens.copy(), top=top))
        old_function = with_deprecation_context(
            matrix_ptr.load_ptr(),
            matrix_ptr=matrix_ptr,
            abstract_tree=abstract_tree,
            tokens=tokens,
            top=top)

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_function('device')

        self.assertEqual(result, ('old', 'device'))
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _deprecated_revision_api.__module__,
                _deprecated_revision_api.__qualname__,
                _latest_revision_api.__module__,
                _latest_revision_api.__qualname__))

    def test_deprecated_abstract_context_latest_revision_class(self):
        from genie.abstract.decorator import with_deprecation_context

        top = 'DeprecatedRevisionClass'
        abstract_tree = _revision_tree(
            top, '_DeprecatedRevisionClass', '_LatestRevisionClass')
        tokens = {'os': ['iosxe'], 'revision': [None]}
        matrix_ptr = next(abstract_tree.iter_lookup(
            tokens=tokens.copy(), top=top))
        old_class = with_deprecation_context(
            matrix_ptr.load_ptr(),
            matrix_ptr=matrix_ptr,
            abstract_tree=abstract_tree,
            tokens=tokens,
            top=top)

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            instance = old_class('device')

        self.assertTrue(inspect.isclass(old_class))
        self.assertIsInstance(instance, _DeprecatedRevisionClass)
        self.assertEqual(instance.device, 'device')
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _DeprecatedRevisionClass.__module__,
                _DeprecatedRevisionClass.__qualname__,
                _LatestRevisionClass.__module__,
                _LatestRevisionClass.__qualname__))

    def test_deprecated_abstract_context_latest_revision_class_member(self):
        from genie.abstract.decorator import with_deprecation_context

        command = 'show deprecated revision'
        abstract_tree = _revision_tree(
            command, '_DeprecatedMemberClass', '_LatestMemberClass')
        tokens = {'os': ['iosxe'], 'revision': [None]}
        matrix_ptr = next(abstract_tree.iter_lookup(
            tokens=tokens.copy(), top=command))
        old_class = with_deprecation_context(
            matrix_ptr.load_ptr(),
            matrix_ptr=matrix_ptr,
            abstract_tree=abstract_tree,
            tokens=tokens,
            top=command)

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = old_class().cli(output='')

        self.assertEqual(result, {'key': 'Hello World'})
        self.assertTrue(inspect.isclass(old_class))
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _DeprecatedMemberClass.cli.__module__,
                _DeprecatedMemberClass.cli.__qualname__,
                _LatestMemberClass.cli.__module__,
                _LatestMemberClass.cli.__qualname__))

    def test_deprecated_abstract_context_does_not_suggest_older_revision(self):
        from genie.abstract.decorator import with_deprecation_context
        from genie.abstract.package import AbstractTree

        top = 'DeprecatedLatestRevisionClass'
        abstract_tree = AbstractTree.from_json({
            top: {
                'folders': {
                    'iosxe': {
                        'tokens': {'os': 'iosxe'},
                        'folders': {
                            'rv1': {
                                'package': 'genie.tests.abstract',
                                'module_name': 'test_decorator',
                                'class': '_LatestRevisionClass',
                                'tokens': {'revision': '1'},
                            },
                            'rv2': {
                                'package': 'genie.tests.abstract',
                                'module_name': 'test_decorator',
                                'class': '_DeprecatedRevisionClass',
                                'tokens': {'revision': '2'},
                            },
                        },
                    },
                },
            },
        })
        tokens = {'os': ['iosxe'], 'revision': ['2']}
        matrix_ptr = next(abstract_tree.iter_lookup(
            tokens=tokens.copy(), top=top))
        old_class = with_deprecation_context(
            matrix_ptr.load_ptr(),
            matrix_ptr=matrix_ptr,
            abstract_tree=abstract_tree,
            tokens=tokens,
            top=top)

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            old_class('device')

        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated.'.format(
                _DeprecatedRevisionClass.__module__,
                _DeprecatedRevisionClass.__qualname__))

    @unittest.skipUnless(
        _module_available('genie.libs.sdk.apis'),
        'genie.libs.sdk is not installed alongside genie')
    def test_genielibs_sdk_api_get_api_adds_deprecation_context(self):
        from genie.conf.base.api import API

        api_name = 'deprecated_revision_api'
        api = API.__new__(API)
        api.function_data = _revision_tree(
            api_name,
            '_deprecated_revision_api',
            '_latest_revision_api',
            feature='sdk')

        func = api.get_api(
            api_name,
            device=_Device(revision=[None]))

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = func('device')

        self.assertEqual(result, ('old', 'device'))
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _deprecated_revision_api.__module__,
                _deprecated_revision_api.__qualname__,
                _latest_revision_api.__module__,
                _latest_revision_api.__qualname__))

    @unittest.skipUnless(
        _module_available('genie.libs.parser.utils.common'),
        'genieparser is not installed alongside genie')
    def test_genieparser_get_parser_cls_adds_member_deprecation_context(self):
        from genie.libs.parser.utils import common as parser_common

        command = 'show deprecated revision'
        parser_data = _revision_tree(
            command,
            '_DeprecatedMemberClass',
            '_LatestMemberClass',
            feature='parser')

        old_parser_data = parser_common.parser_data
        parser_common.parser_data = parser_data
        try:
            parser_class = parser_common._get_parser_cls(
                command,
                {'os': ['iosxe'], 'revision': [None]})
        finally:
            parser_common.parser_data = old_parser_data

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            result = parser_class().cli(output='')

        self.assertEqual(result, {'key': 'Hello World'})
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _DeprecatedMemberClass.cli.__module__,
                _DeprecatedMemberClass.cli.__qualname__,
                _LatestMemberClass.cli.__module__,
                _LatestMemberClass.cli.__qualname__))

    @unittest.skipUnless(
        _module_available('genie.libs.clean.utils'),
        'genie.libs.clean is not installed alongside genie')
    def test_genielibs_clean_get_clean_function_adds_deprecation_context(self):
        from genie.libs.clean import utils as clean_utils

        stage_name = 'DeprecatedRevisionClass'
        clean_data = _revision_tree(
            stage_name,
            '_DeprecatedRevisionClass',
            '_LatestRevisionClass')

        stage_class = clean_utils.get_clean_function(
            stage_name,
            clean_data,
            _Device(revision=[None]))

        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always')
            instance = stage_class('device')

        self.assertIsInstance(instance, _DeprecatedRevisionClass)
        self.assertEqual(instance.device, 'device')
        self.assertEqual(len(caught), 1)
        self.assertEqual(
            str(caught[0].message),
            '{}.{} is deprecated. Use {}.{} (revision 1) instead.'.format(
                _DeprecatedRevisionClass.__module__,
                _DeprecatedRevisionClass.__qualname__,
                _LatestRevisionClass.__module__,
                _LatestRevisionClass.__qualname__))

